def run(doc):
    TARGET_COMPANY = "Motley Terpz"
    TARGET_WAREHOUSE = "Nature's Lab - MT"
    ROOT_ITEM_GROUP = "Motley Terpz"
    SLACK_CHANNEL = "#conversions-motley"

    if doc.company != TARGET_COMPANY:
        return

    webhook_url = frappe.conf.get("slack_motley_webhook")
    if not webhook_url:
        frappe.log_error("slack_motley_webhook not set in site_config.json", "Motley Terpz Slack")
        return

    checked_count = 0
    required_map = {}
    label_map = {}
    uom_map = {}

    def item_is_under_root_group(item_code):
        item_group = frappe.db.get_value("Item", item_code, "item_group")
        if not item_group:
            return False
        if item_group == ROOT_ITEM_GROUP:
            return True
        root = frappe.db.get_value("Item Group", ROOT_ITEM_GROUP, ["lft", "rgt"], as_dict=True)
        grp = frappe.db.get_value("Item Group", item_group, ["lft", "rgt"], as_dict=True)
        if not root or not grp:
            return False
        return grp.lft >= root.lft and grp.rgt <= root.rgt

    def available_qty(item_code):
        return float(
            frappe.db.get_value(
                "Bin",
                {"item_code": item_code, "warehouse": TARGET_WAREHOUSE},
                "actual_qty"
            ) or 0
        )

    for row in doc.items:
        if not row.item_code:
            continue
        if not item_is_under_root_group(row.item_code):
            continue
        checked_count += 1
        label_map[row.item_code] = row.item_name or row.item_code
        uom_map[row.item_code] = row.stock_uom or ""
        required_qty = float(row.stock_qty or 0)
        required_map[row.item_code] = required_map.get(row.item_code, 0) + required_qty

    if checked_count == 0:
        return

    need_lines = []
    ok_lines = []

    for item_code in required_map:
        required_qty = required_map[item_code]
        available = available_qty(item_code)
        shortage = max(0, required_qty - available)
        label = label_map[item_code]
        suom = uom_map[item_code]

        if shortage > 0:
            need_lines.append(
                "• *{0}* — need *{1:.2f} {2}* (required {3:.2f}, available {4:.2f})".format(
                    label, shortage, suom, required_qty, available
                )
            )
        else:
            ok_lines.append(
                "• {0} — ok ({1:.2f} {2})".format(label, required_qty, suom)
            )

    header = ":red_circle: Conversion required" if need_lines else ":large_green_circle: No conversion required"
    invoice_link = frappe.utils.get_url("/app/sales-invoice/" + doc.name)

    blocks = [
        {
            "type": "header",
            "text": {"type": "plain_text", "text": header}
        },
        {
            "type": "section",
            "text": {
                "type": "mrkdwn",
                "text": "*Invoice:* <{0}|{1}>\n*Customer:* {2}\n*Warehouse:* {3}".format(
                    invoice_link, doc.name, doc.customer, TARGET_WAREHOUSE
                )
            }
        },
        {"type": "divider"}
    ]

    if need_lines:
        blocks.append({
            "type": "section",
            "text": {
                "type": "mrkdwn",
                "text": ":warning: *Needs conversion*\n" + "\n".join(need_lines)
            }
        })

    if ok_lines:
        blocks.append({"type": "divider"})
        blocks.append({
            "type": "section",
            "text": {
                "type": "mrkdwn",
                "text": "*Items OK*\n" + "\n".join(ok_lines[:10])
            }
        })

    payload = {
        "channel": SLACK_CHANNEL,
        "text": doc.name + " inventory check",
        "blocks": blocks
    }

    # Send to Slack using stdlib http.client (works in Frappe sandbox)
    try:
        import json
        import http.client
        import ssl

        body = json.dumps(payload)
        context = ssl.create_default_context()

        conn = http.client.HTTPSConnection("hooks.slack.com", context=context)
        conn.request(
            "POST",
            "/services/T07R5GVLV6K/B0ACPNX0TGE/G6ESyyFbpr1R83z9xTJlcsfp",
            body=body,
            headers={"Content-Type": "application/json"}
        )
        resp = conn.getresponse()
        if resp.status != 200:
            frappe.log_error(
                "Slack error {0}: {1}".format(resp.status, resp.read().decode()),
                "Motley Terpz Slack"
            )
        conn.close()
    except Exception as e:
        frappe.log_error(str(e), "Motley Terpz Slack")

run(doc)
